content.internal/engine/specs/agents/check_devia:
{
 "name": "check_deviation",
 "kind": "subagent",
 "class": "evidence",
 "maxTurns": 5,
 "role": "specialist",
 "allowed": [
  "retrieve"
 ],
 "description": "Checks one requirement of a controlling document (instructions, a term sheet, a playbook) against the documents under review, part by part: conform, deviate or omitted, with a severity and a correction. The requirement is the controlling document's own words, quoted verbatim from requirementDocId (one of controllingDocIds) and verified like any quote; a paraphrase is refused with the closest passage to quote instead. Go reads the requirement in its section of the document's section tree (the whole section, before and after it, with the headings above): the subagent judges against that section, its controlling quote must lie in it, an independent check confirms the section imposes the requirement as each verdict states it, and each finding quotes the section. Each deviation must quote both sides verbatim; an omission is kept only when the provision does not verify in the named reviewed document (string match, then the paraphrase judge on its closest passage). Values in a correction must come from the quotes (or simple sums and differences of them); others are withheld and flagged. It returns the resulting finding ids. Do not use it for facts in one document (extract_facts) or for numeric conflicts across documents (join_discrepancies).\nExample: {\"requirement\": \"The residuary estate shall be divided equally among the three children.\", \"requirementDocId\": \"3f6c2a9e-0b1d-4c2e-9a7f-5d8e1b2c4a6f\", \"controllingDocIds\": [\"3f6c2a9e-0b1d-4c2e-9a7f-5d8e1b2c4a6f\"], \"reviewedDocIds\": [\"7a1b2c3d-4e5f-4a6b-8c7d-9e0f1a2b3c4d\"], \"issueId\": \"I4\"}",
 "in": {
  "type": "object",
  "additionalProperties": false,
  "required": [
   "requirement",
   "requirementDocId",
   "controllingDocIds",
   "reviewedDocIds",
   "issueId"
  ],
  "properties": {
   "requirement": {
    "type": "string",
    "maxLength": 2000,
    "minLength": 1
   },
   "requirementDocId": {
    "type": "string",
    "maxLength": 64
   },
   "controllingDocIds": {
    "type": "array",
    "items": {
     "type": "string",
     "maxLength": 64
    },
    "maxItems": 20
   },
   "reviewedDocIds": {
    "type": "array",
    "items": {
     "type": "string",
     "maxLength": 64
    },
    "maxItems": 20
   },
   "issueId": {
    "type": [
     "string",
     "null"
    ],
    "maxLength": 16
   }
  }
 },
 "out": {
  "type": "object",
  "additionalProperties": false,
  "required": [
   "verdicts"
  ],
  "properties": {
   "verdicts": {
    "type": "array",
    "items": {
     "type": "object",
     "additionalProperties": false,
     "required": [
      "part",
      "verdict",
      "severity",
      "correction",
      "document",
      "controlling",
      "reviewed"
     ],
     "properties": {
      "part": {
       "type": "string",
       "maxLength": 1000
      },
      "verdict": {
       "type": "string",
       "enum": [
        "conform",
        "deviate",
        "omitted"
       ]
      },
      "severity": {
       "type": "string",
       "enum": [
        "HIGH",
        "MEDIUM",
        "LOW"
       ]
      },
      "correction": {
       "type": "string",
       "maxLength": 2000
      },
      "document": {
       "type": "string",
       "maxLength": 64
      },
      "controlling": {
       "type": "object",
       "additionalProperties": false,
       "required": [
        "documentId",
        "quote"
       ],
       "properties": {
        "documentId": {
         "type": "string",
         "maxLength": 64
        },
        "quote": {
         "type": "string",
         "maxLength": 4000,
         "minLength": 1
        }
       }
